package store

import (
	"encoding/json"
	"time"
)

// IDs are PostgreSQL uuids generated by the database and carried as their
// canonical string form in Go.

// Encrypted is an envelope-encrypted value as the crypto package produces it
// and as every secret column group stores it: which master key wrapped the
// per-record data key, the wrapped data key, the AEAD nonce and the
// ciphertext. The AEAD associated data (user, connection, app) is recomputed
// on decrypt and never stored.
type Encrypted struct {
	KeyID          string
	WrappedDataKey []byte
	Nonce          []byte
	Ciphertext     []byte
}

// User statuses.
const (
	UserActive   = "active"
	UserDisabled = "disabled"
)

// User is a person who signed in with the company identity provider.
type User struct {
	ID                   string
	DisplayName          string
	Status               string
	LastCompanySignInAt  *time.Time
	DisabledAt           *time.Time
	CreatedAt, UpdatedAt time.Time
}

// Identity is one provider issuer + permanent subject pair bound to a user.
type Identity struct {
	ID           string
	UserID       string
	Issuer       string
	Subject      string
	LastSignInAt *time.Time
	CreatedAt    time.Time
}

// Session is a portal / OAuth browser session; only the hash of its secret is stored.
type Session struct {
	ID         string
	UserID     string
	TokenHash  []byte
	CreatedAt  time.Time
	ExpiresAt  time.Time
	LastSeenAt *time.Time
	RevokedAt  *time.Time
}

// Role is an admin-defined structured role (decision 490o45d0).
type Role struct {
	ID                   string
	Name                 string
	Description          string
	Definition           json.RawMessage
	IsDefault            bool
	CreatedAt, UpdatedAt time.Time
}

// RoleAssignment binds a user to a role.
type RoleAssignment struct {
	UserID     string
	RoleID     string
	AssignedBy *string
	CreatedAt  time.Time
}

// PolicyVersion is one compiled Cedar policy set identified by its hash.
type PolicyVersion struct {
	ID          string
	VersionHash string
	Cedar       string
	Source      json.RawMessage
	CreatedAt   time.Time
}

// UserRestriction narrows a user's role further.
type UserRestriction struct {
	ID                   string
	UserID               string
	Definition           json.RawMessage
	CreatedBy            *string
	CreatedAt, UpdatedAt time.Time
}

// Token is a generated mgw_ token (decision uamxx6ba); the secret is stored as
// its SHA-256 hash. PublicID is the 8-character id embedded in the token
// string (mgw_<PublicID>_<secret>), unique across all users. Scope is nil
// for "everything the user may do".
type Token struct {
	ID         string
	UserID     string
	PublicID   string
	Name       string
	TokenHash  []byte
	ReadOnly   bool
	Scope      json.RawMessage
	ExpiresAt  time.Time
	RevokedAt  *time.Time
	LastUsedAt *time.Time
	CreatedAt  time.Time
}

// OAuthClient is a dynamically registered MCP client (harness).
type OAuthClient struct {
	ID               string
	ClientID         string
	ClientSecretHash []byte
	ClientName       string
	RedirectURIs     []string
	Metadata         json.RawMessage
	CreatedAt        time.Time
	LastUsedAt       *time.Time
}

// OAuthRefreshToken is one link in a rotating refresh-token chain.
type OAuthRefreshToken struct {
	ID          string
	UserID      string
	ClientID    string
	TokenHash   []byte
	Scope       json.RawMessage
	IssuedAt    time.Time
	ExpiresAt   time.Time
	RotatedFrom *string
	RevokedAt   *time.Time
	LastUsedAt  *time.Time
}

// VendorApp is an admin-registered OAuth app at a vendor (decision mh7c6z3v).
type VendorApp struct {
	ID                   string
	Vendor               string
	Name                 string
	ClientID             string
	ClientSecret         Encrypted
	Config               json.RawMessage
	Enabled              bool
	CreatedAt, UpdatedAt time.Time
}

// Account labels and connection statuses.
const (
	AccountCompany  = "company"
	AccountPersonal = "personal"

	ConnectionActive         = "active"
	ConnectionNeedsReconnect = "needs_reconnect"
	ConnectionRevoked        = "revoked"
)

// Connection binds a user to one permanent external account of a vendor app.
type Connection struct {
	ID                   string
	UserID               string
	VendorAppID          string
	ExternalAccountID    string
	Label                string
	DisplayName          string
	Scopes               []string
	Status               string
	LastRefreshedAt      *time.Time
	CreatedAt, UpdatedAt time.Time
}

// ConnectionSecret is the envelope-encrypted vendor token bundle of a connection.
type ConnectionSecret struct {
	ConnectionID   string
	UserID         string
	Secret         Encrypted
	TokenExpiresAt *time.Time
	UpdatedAt      time.Time
}

// Approval statuses.
const (
	ApprovalPending  = "pending"
	ApprovalApproved = "approved"
	ApprovalDenied   = "denied"
	ApprovalConsumed = "consumed"
	ApprovalExpired  = "expired"
)

// Approval is a durable confirmation request (decision s0p05diu). Payload is
// the encrypted canonical arguments while pending and nil afterwards.
type Approval struct {
	ID              string
	UserID          string
	ConnectionID    string
	Tool            string
	Digest          []byte
	Payload         *Encrypted
	Status          string
	PolicyVersionID string
	CreatedAt       time.Time
	ExpiresAt       time.Time
	DecidedAt       *time.Time
	ConsumedAt      *time.Time
}

// Ledger states (decision dovthftx).
const (
	LedgerInProgress = "in_progress"
	LedgerSucceeded  = "succeeded"
	LedgerFailed     = "failed"
	LedgerUnknown    = "unknown"
	LedgerUnresolved = "unresolved"
)

// LedgerOperation is one write intent and its outcome; result IDs only.
type LedgerOperation struct {
	ID                   string
	UserID               string
	ConnectionID         string
	Tool                 string
	State                string
	IdempotencyKey       string
	WindowStart          time.Time
	WindowEnd            time.Time
	ApprovalID           *string
	Digest               []byte
	PolicyVersionID      string
	ResultIDs            json.RawMessage
	ErrorCode            *string
	ReconcileAttempts    int
	CreatedAt, UpdatedAt time.Time
	FinishedAt           *time.Time
}

// Ledger attempt kinds.
const (
	AttemptCall      = "call"
	AttemptReconcile = "reconcile"
)

// LedgerAttempt is one app call or reconciler check for an operation.
type LedgerAttempt struct {
	ID          string
	OperationID string
	UserID      string
	AttemptNo   int
	Kind        string
	Outcome     string
	ErrorCode   *string
	StartedAt   time.Time
	FinishedAt  *time.Time
}

// AuditEvent is one append-only audit row: metadata only, never arguments or
// content. UserID is nil for system events.
type AuditEvent struct {
	ID              string
	EventType       string
	UserID          *string
	ActorUserID     *string
	TokenID         *string
	Tool            *string
	ConnectionID    *string
	AccountLabel    *string
	Resource        json.RawMessage
	Decision        string
	PolicyVersionID *string
	ApprovalID      *string
	OperationID     *string
	Outcome         *string
	LatencyMS       *int
	Details         json.RawMessage
	CreatedAt       time.Time
}

// Signing key statuses.
const (
	SigningKeyActive  = "active"
	SigningKeyRetired = "retired"
)

// SigningKey signs the gateway's own OAuth access tokens.
type SigningKey struct {
	ID         string
	KID        string
	Algorithm  string
	PublicKey  []byte
	PrivateKey Encrypted
	Status     string
	CreatedAt  time.Time
	RetiredAt  *time.Time
}

// JobLock is a lease that makes a background worker run on one replica.
type JobLock struct {
	Name       string
	Holder     string
	AcquiredAt time.Time
	ExpiresAt  time.Time
}
